-- Permit waiting songs while retaining one running separation per band.
-- Existing role grants, RLS, storage reservations and minute allowances are unchanged.
drop index public.one_active_job_per_band;
create unique index one_processing_job_per_band on public.processing_jobs(band_id) where status='processing';
create index processing_queue_order on public.processing_jobs(band_id,created_at,id) where status='queued';

create or replace function public.submit_separation(b uuid,s uuid,input uuid,job uuid,idem text) returns public.processing_jobs language plpgsql security definer set search_path=public as $$declare e public.entitlements;u public.band_usage;a public.audio_assets;c public.platform_config;j public.processing_jobs;monthly bigint;global_used bigint;reserve bigint;begin
 if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Editor permission required';end if;
 select * into c from public.platform_config where id=true for update;
 select * into j from public.processing_jobs where band_id=b and idempotency_key=idem;if found then return j;end if;
 if not c.ai_enabled then raise exception 'BR:AI processing is currently unavailable';end if;
 select * into u from public.band_usage where band_id=b for update;select * into e from public.entitlements where band_id=b;select * into a from public.audio_assets where id=input and song_id=s and band_id=b and source='original' and status<>'deleting';
 if not found or a.duration>e.ai_seconds_limit then raise exception 'BR:Input missing or exceeds AI duration allowance';end if;
 if exists(select 1 from public.processing_jobs where band_id=b and input_asset_id=input and status in ('queued','processing')) then raise exception 'BR:A job is already active for this recording';end if;
 if (select count(*) from public.processing_jobs where band_id=b and status in ('queued','processing'))>=20 then raise exception 'BR:Your band queue is full (20 songs). Wait for a song to finish and retry.';end if;
 select coalesce(sum(seconds),0) into monthly from public.processing_usage where band_id=b and month=date_trunc('month',now())::date and state in ('reserved','consumed');
 select coalesce(sum(seconds),0) into global_used from public.processing_usage where month=date_trunc('month',now())::date and state in ('reserved','consumed');
 if monthly+ceil(a.duration)>e.ai_monthly_seconds or global_used+ceil(a.duration)>c.monthly_ai_seconds_cap then raise exception 'BR:Processing allowance reached';end if;
 reserve=ceil(a.duration)::bigint*44100*6*4+1048576;
 if u.stored_bytes+u.reserved_bytes+reserve>e.storage_limit then raise exception 'BR:Not enough space for four lossless stems';end if;
 insert into public.processing_jobs(id,band_id,song_id,input_asset_id,created_by,idempotency_key,duration_seconds,output_reserved_bytes) values(job,b,s,input,auth.uid(),idem,ceil(a.duration),reserve) returning * into j;
 update public.band_usage set reserved_bytes=reserved_bytes+reserve where band_id=b;insert into public.processing_usage(job_id,band_id,month,seconds,state) values(job,b,date_trunc('month',now())::date,ceil(a.duration),'reserved');return j;
end$$;

create or replace function public.retry_separation(job uuid) returns public.processing_jobs language plpgsql security definer set search_path=public as $$declare j public.processing_jobs;e public.entitlements;u public.band_usage;c public.platform_config;monthly bigint;global_used bigint;begin select * into j from public.processing_jobs where id=job for update;if not public.band_permission(j.band_id,array['owner','admin','editor']::public.band_role[]) or j.status<>'failed' or j.attempt>=j.max_attempts then raise exception 'BR:Retry unavailable';end if;if not exists(select 1 from public.audio_assets where id=j.input_asset_id and status='verified') then raise exception 'BR:Original is unavailable or invalid. Upload a decodable recording to create a new job.';end if;select * into c from public.platform_config where id=true for update;if not c.ai_enabled then raise exception 'BR:AI disabled';end if;select * into u from public.band_usage where band_id=j.band_id for update;select * into e from public.entitlements where band_id=j.band_id;if u.stored_bytes+u.reserved_bytes+j.output_reserved_bytes>e.storage_limit or (select count(*) from public.processing_jobs where band_id=j.band_id and status in ('queued','processing'))>=20 then raise exception 'BR:Storage allowance or queue limit reached';end if;select coalesce(sum(seconds),0) into monthly from public.processing_usage where band_id=j.band_id and month=date_trunc('month',now())::date and state in ('consumed','reserved');select coalesce(sum(seconds),0) into global_used from public.processing_usage where month=date_trunc('month',now())::date and state in ('consumed','reserved');if monthly+(case when exists(select 1 from public.processing_usage where job_id=job and state='consumed') then 0 else j.duration_seconds end)>e.ai_monthly_seconds or global_used+(case when exists(select 1 from public.processing_usage where job_id=job and state='consumed') then 0 else j.duration_seconds end)>c.monthly_ai_seconds_cap then raise exception 'BR:Processing allowance reached';end if;update public.processing_jobs set status='queued',error=null,lease_hash=null,updated_at=now() where id=job returning * into j;update public.band_usage set reserved_bytes=reserved_bytes+j.output_reserved_bytes where band_id=j.band_id;update public.processing_usage set state='reserved',month=date_trunc('month',now())::date where job_id=job and state='released';return j;end$$;

create or replace function public.claim_desktop_job(hash text,b uuid) returns jsonb language plpgsql security invoker set search_path=public as $$declare v public.verification_tasks;j public.processing_jobs;a public.audio_assets;begin
 -- Serialize short claims across worker identities; audio inference never holds this lock.
 perform pg_advisory_xact_lock(171992819);

 select * into v from public.verification_tasks where exists(select 1 from public.audio_assets aa join public.bands bb on bb.id=aa.band_id where aa.id=asset_id and aa.band_id=b and not bb.suspended) and (status='queued' or status='processing' and lease_expires_at<now()) and attempt<3 order by created_at for update skip locked limit 1;
 if found then update public.verification_tasks set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '5 minutes' where id=v.id;select * into a from public.audio_assets where id=v.asset_id;return jsonb_build_object('kind','verification','id',v.id,'asset',to_jsonb(a));end if;
 select p.* into j from public.processing_jobs p join public.audio_assets aa on aa.id=p.input_asset_id join public.bands bb on bb.id=p.band_id where p.band_id=claim_desktop_job.b and not exists(select 1 from public.processing_jobs active where active.band_id=p.band_id and active.id<>p.id and active.status='processing') and (p.status='queued' or p.status='processing' and p.lease_expires_at<now()) and p.attempt<p.max_attempts and aa.status='verified' and not bb.suspended and (select ai_enabled from public.platform_config where id=true) order by (p.status='processing') desc,p.created_at,p.id for update of p skip locked limit 1;
 if found then update public.processing_jobs set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '10 minutes',updated_at=now() where id=j.id;update public.processing_usage set state='consumed' where job_id=j.id;select * into a from public.audio_assets where id=j.input_asset_id;return jsonb_build_object('kind','separation','id',j.id,'asset',to_jsonb(a),'band_id',j.band_id,'song_id',j.song_id,'max_seconds',j.duration_seconds);end if;return null;
end$$;

create or replace function public.claim_job(hash text) returns jsonb language plpgsql security definer set search_path=public as $$declare v public.verification_tasks;j public.processing_jobs;a public.audio_assets;begin
 perform pg_advisory_xact_lock(171992819);
 update public.platform_config set worker_online_at=now() where id=true;
 select * into v from public.verification_tasks where status='queued' or status='processing' and lease_expires_at<now() and attempt<3 order by created_at for update skip locked limit 1;
 if found then update public.verification_tasks set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '5 minutes' where id=v.id;select * into a from public.audio_assets where id=v.asset_id;return jsonb_build_object('kind','verification','id',v.id,'asset',to_jsonb(a));end if;
 select p.* into j from public.processing_jobs p join public.audio_assets aa on aa.id=p.input_asset_id join public.bands b on b.id=p.band_id where not exists(select 1 from public.processing_jobs active where active.band_id=p.band_id and active.id<>p.id and active.status='processing') and (p.status='queued' or p.status='processing' and p.lease_expires_at<now()) and p.attempt<p.max_attempts and aa.status='verified' and not b.suspended and (select ai_enabled from public.platform_config where id=true) order by (p.status='processing') desc,p.created_at,p.id for update of p skip locked limit 1;
 if found then update public.processing_jobs set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '10 minutes',updated_at=now() where id=j.id;update public.processing_usage set state='consumed' where job_id=j.id;select * into a from public.audio_assets where id=j.input_asset_id;return jsonb_build_object('kind','separation','id',j.id,'asset',to_jsonb(a),'band_id',j.band_id,'song_id',j.song_id,'max_seconds',j.duration_seconds);end if;return null;
end$$;
